/**
 * @summary Upload a book (admin only)
 */
export const getUploadBookUrl = () => {
  return `/api/books/upload`;
};

export const uploadBook = async (
  uploadBookRequest: UploadBookRequest,
  options?: RequestInit,
): Promise<Book> => {
  const formData = new FormData();
  formData.append(`title`, uploadBookRequest.title);
  if (uploadBookRequest.author !== undefined) {
    formData.append(`author`, uploadBookRequest.author);
  }
  if (uploadBookRequest.description !== undefined) {
    formData.append(`description`, uploadBookRequest.description);
  }
  if (uploadBookRequest.category !== undefined) {
    formData.append(`category`, uploadBookRequest.category);
  }
  formData.append(`file`, uploadBookRequest.file);

  return customFetch<Book>(getUploadBookUrl(), {
    ...options,
    method: "POST",
    body: formData,
  });
};

